package com.bank.swap;

import java.util.Arrays;
import java.util.logging.Logger;

// In-place swaps without a temporary for National Bank of India ledger passes.
public class SwapService {
    private static final Logger log = Logger.getLogger(SwapService.class.getName());

    // Swaps two array slots with XOR; MUST guard against aliasing (i == j).
    public void xorSwap(int[] arr, int i, int j) {
        if (i == j) {
            // Same slot: XOR would zero the value out. Do nothing.
            log.fine(() -> "xorSwap skipped: aliasing at index " + i);
            return;
        }
        arr[i] = arr[i] ^ arr[j];   // combined bits in arr[i]
        arr[j] = arr[i] ^ arr[j];   // cancels original arr[j], leaves original arr[i]
        arr[i] = arr[i] ^ arr[j];   // cancels original arr[i], leaves original arr[j]
        log.fine(() -> "xorSwap done on indices " + i + "," + j);
    }

    // Swaps two scalar values with addition/subtraction and returns the pair.
    public int[] arithmeticSwap(int a, int b) {
        a = a + b;   // a holds the sum (may overflow but result stays correct mod 2^32)
        b = a - b;   // b becomes original a
        a = a - b;   // a becomes original b
        int fa = a, fb = b;
        log.fine(() -> "arithmeticSwap result a=" + fa + " b=" + fb);
        return new int[]{a, b};
    }
}
