package com.bank.swap;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: swap balances and ledger slots without a temporary.
public class SwapDemo {
    private static final Logger log = Logger.getLogger(SwapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        SwapService service = new SwapService();

        // Scalar swap of Rajesh and Priya balances (in thousands for the demo).
        int rajesh = 1000;   // SAV2001
        int priya  = 250;    // CUR3001
        int[] swapped = service.arithmeticSwap(rajesh, priya);
        log.info(() -> "After arithmetic swap: Rajesh=" + swapped[0] + " Priya=" + swapped[1]);

        // In-place ledger slot swap with aliasing guard.
        int[] ledger = {1000, 250, 500};
        service.xorSwap(ledger, 0, 1);
        log.info(() -> "After xorSwap(0,1): " + Arrays.toString(ledger));
        service.xorSwap(ledger, 2, 2);   // aliasing: no-op, value preserved
        log.info(() -> "After xorSwap(2,2) aliasing guard: " + Arrays.toString(ledger));
    }
}
